java('ledger-domain','Money','''import java.math.*;
import java.util.Map;
public record Money(String currency, BigInteger minor) {
 public static final Map<String,Integer> SCALES=Map.of("CAD",2,"USD",2,"JPY",0);
 public static final BigInteger MAX=new BigInteger("999999999999999999999999999999");
 public Money { if(!SCALES.containsKey(currency)) throw new IllegalArgumentException("CURRENCY"); if(minor==null||minor.abs().compareTo(MAX)>0) throw new IllegalArgumentException("AMOUNT_BOUND"); }
 public static Money parse(String currency,String decimal) { if(decimal==null||!decimal.matches("-?(0|[1-9][0-9]*)(\\\\.[0-9]+)?")||!SCALES.containsKey(currency))throw new IllegalArgumentException("DECIMAL"); var d=new BigDecimal(decimal); if(d.scale()>SCALES.get(currency))throw new IllegalArgumentException("SCALE"); return new Money(currency,d.movePointRight(SCALES.get(currency)).toBigIntegerExact()); }
 public String decimal(){return new BigDecimal(minor,SCALES.get(currency)).toPlainString();}
}''')
java('ledger-domain','Journal','''import java.math.*; import java.time.*; import java.util.*; import java.security.*; import java.nio.charset.StandardCharsets;
public record Journal(UUID period, LocalDate date, String currency, String reference, List<Line> lines) {
 public enum Side { DEBIT,CREDIT; public Side opposite(){return this==DEBIT?CREDIT:DEBIT;} }
 public record Line(UUID account,Side side,BigInteger minor){public Line{Objects.requireNonNull(account);Objects.requireNonNull(side);if(minor==null||minor.signum()<=0||minor.compareTo(Money.MAX)>0)throw new IllegalArgumentException("POSITIVE_BOUNDED_AMOUNT");}}
 public Journal { Objects.requireNonNull(period);Objects.requireNonNull(date);if(!Money.SCALES.containsKey(currency))throw new IllegalArgumentException("CURRENCY");if(reference==null||reference.length()>120)throw new IllegalArgumentException("REFERENCE");lines=List.copyOf(lines);if(lines.size()<2||lines.size()>100)throw new IllegalArgumentException("BATCH_BOUND");var debit=BigInteger.ZERO;var credit=BigInteger.ZERO;for(var l:lines)if(l.side()==Side.DEBIT)debit=debit.add(l.minor());else credit=credit.add(l.minor());if(!debit.equals(credit)||debit.compareTo(Money.MAX)>0)throw new IllegalArgumentException("UNBALANCED_OR_OVERFLOW"); }
 public Journal reversed(LocalDate when){return new Journal(period,when,currency,"reversal:"+reference,lines.stream().map(l->new Line(l.account(),l.side().opposite(),l.minor())).toList());}
 public String digest(){try{var s=period+"|"+date+"|"+currency+"|"+reference+"|"+lines.stream().map(l->l.account()+":"+l.side()+":"+l.minor()).sorted().toList();return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}''')
java('ledger-domain','ReferenceLedger','''import java.math.*; import java.util.*;
/** Independent signed-sum oracle: debit minus credit; display reverses for credit-normal accounts. */
public final class ReferenceLedger {
 private final Map<UUID,BigInteger> totals=new HashMap<>();
 public void apply(Journal j){var next=new HashMap<>(totals);for(var l:j.lines()){var n=next.getOrDefault(l.account(),BigInteger.ZERO).add(l.side()==Journal.Side.DEBIT?l.minor():l.minor().negate());if(n.abs().compareTo(Money.MAX)>0)throw new IllegalArgumentException("BALANCE_BOUND");next.put(l.account(),n);}totals.clear();totals.putAll(next);}
 public Map<UUID,BigInteger> balances(){return Map.copyOf(totals);}
 public BigInteger displayed(UUID id,Journal.Side normal){return totals.getOrDefault(id,BigInteger.ZERO).multiply(normal==Journal.Side.DEBIT?BigInteger.ONE:BigInteger.ONE.negate());}
}''')
java('ledger-persistence','LedgerStore','''import java.sql.*;import java.util.*;import java.time.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.function.*;import org.flywaydb.core.Flyway;
public final class LedgerStore {
 public record Failure(String code, boolean temporary){}
 public static final class LedgerException extends RuntimeException { public final String code;public final boolean temporary;LedgerException(String c,boolean t,Throwable e){super(c,e);code=c;temporary=t;} }
 private final String url,user,password;
 public LedgerStore(String url,String user,String password){this.url=url;this.user=user;this.password=password;}
 public static void migrate(String url,String user,String password){Flyway.configure().dataSource(url,user,password).locations("classpath:db/migration").load().migrate();}
 @FunctionalInterface public interface SqlWork<T>{T run(Connection c)throws SQLException;}
 public <T>T tx(SqlWork<T> work){for(int attempt=0;attempt<12;attempt++){try(var c=DriverManager.getConnection(url,user,password)){c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE);try(var st=c.createStatement()){st.execute("SET LOCAL statement_timeout='15s'");st.execute("SET LOCAL lock_timeout='10s'");}try{T result=work.run(c);c.commit();return result;}catch(SQLException|RuntimeException e){c.rollback();throw e;}}catch(SQLException e){if(("40001".equals(e.getSQLState())||"40P01".equals(e.getSQLState())||"23505".equals(e.getSQLState()))&&attempt<11){try{Thread.sleep(Math.min(100,2L*(attempt+1)));}catch(InterruptedException x){Thread.currentThread().interrupt();throw new LedgerException("INTERRUPTED",true,x);}continue;}throw new LedgerException(e.getSQLState()!=null&&e.getSQLState().startsWith("P0")?e.getMessage().split("\\\\n")[0]:"DATABASE_REJECTED", "40001".equals(e.getSQLState())||"40P01".equals(e.getSQLState()),e);}}throw new IllegalStateException();}
 public static int execute(Connection c,String sql,Object... args)throws SQLException{try(var p=c.prepareStatement(sql)){bind(p,args);return p.executeUpdate();}}
 public static List<Map<String,String>> query(Connection c,String sql,Object...args)throws SQLException{try(var p=c.prepareStatement(sql)){bind(p,args);try(var r=p.executeQuery()){var list=new ArrayList<Map<String,String>>();while(r.next()){var m=new LinkedHashMap<String,String>();for(int i=1;i<=r.getMetaData().getColumnCount();i++)m.put(r.getMetaData().getColumnLabel(i),r.getString(i));list.add(m);}return list;}}}
 private static void bind(PreparedStatement p,Object[] args)throws SQLException{for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);}
 public UUID account(UUID tenant, String currency,Journal.Side normal,String name){if(!Money.SCALES.containsKey(currency)||name==null||name.isBlank()||name.length()>120)throw new IllegalArgumentException("ACCOUNT_INPUT");var id=UUID.randomUUID();return tx(c->{execute(c,"INSERT INTO ledger.account VALUES(?,?,?,?,?)",tenant,id,currency,normal.name(),name);return id;});}
 public UUID post(UUID tenant,String key,Journal j){return post(tenant,key,j,null);}
 public UUID post(UUID tenant,String key,Journal j,UUID reversal){if(key==null||key.isBlank()||key.length()>120)throw new IllegalArgumentException("KEY_BOUND");var id=UUID.randomUUID();return tx(c->postOn(c,tenant,key,j,reversal,id));}
 public static UUID postOn(Connection c,UUID tenant,String key,Journal j,UUID reversal,UUID id)throws SQLException{var json=new StringBuilder("[");for(var l:j.lines()){if(json.length()>1)json.append(',');json.append("{\\\"account\\\":\\\"").append(l.account()).append("\\\",\\\"side\\\":\\\"").append(l.side()).append("\\\",\\\"amount\\\":\\\"").append(l.minor()).append("\\\"}");}json.append(']');try(var p=c.prepareStatement("SELECT ledger.post_journal(?,?,?,?,?,?,?,?,?::jsonb,?,?)")){bind(p,new Object[]{tenant,key,j.digest(),id,j.period(),j.date(),j.currency(),j.reference(),json.toString(),reversal,reversal==null?"POST":"REVERSE"});try(var r=p.executeQuery()){r.next();return r.getObject(1,UUID.class);}}}
 public UUID reverse(UUID tenant,UUID original,String key,LocalDate date){return tx(c->{var rows=query(c,"SELECT j.period_id,j.currency,j.reference,p.account_id,p.side,p.amount FROM ledger.journal j JOIN ledger.posting p ON p.tenant_id=j.tenant_id AND p.journal_id=j.id WHERE j.tenant_id=? AND j.id=? ORDER BY p.line_no",tenant,original);if(rows.isEmpty())throw new IllegalArgumentException("JOURNAL_NOT_FOUND");var first=rows.getFirst();var lines=rows.stream().map(r->new Journal.Line(UUID.fromString(r.get("account_id")),Journal.Side.valueOf(r.get("side")).opposite(),new BigInteger(r.get("amount")))).toList();var journal=new Journal(UUID.fromString(first.get("period_id")),date,first.get("currency"),"reversal:"+original,lines);return postOn(c,tenant,key,journal,original,UUID.randomUUID());});}
 public void close(UUID tenant,UUID period){tx(c->{query(c,"SELECT ledger.close_period(?,?)",tenant,period);return null;});}
 public List<Map<String,String>> receipt(UUID tenant,String key){return tx(c->query(c,"SELECT operation,response FROM ledger.idempotency_receipt WHERE tenant_id=? AND key=? ORDER BY operation",tenant,key));}
 /** Cursor is the last journal date/id/line and fixed recorded-at boundary; later requests preserve it. */
 public List<Map<String,String>> statement(UUID tenant,UUID account,LocalDate afterDate,UUID afterId,int afterLine,Instant boundary,int limit){if(limit<1||limit>200)throw new IllegalArgumentException("PAGE_BOUND");return tx(c->query(c,"SELECT j.id,j.effective_date,j.recorded_at,j.currency,j.reference,p.line_no,p.side,p.amount::text FROM ledger.journal j JOIN ledger.posting p ON j.tenant_id=p.tenant_id AND j.id=p.journal_id WHERE p.tenant_id=? AND p.account_id=? AND j.recorded_at<=? AND (j.effective_date,j.id,p.line_no)>(?,?,?) ORDER BY j.effective_date,j.id,p.line_no LIMIT ?",tenant,account,java.sql.Timestamp.from(boundary),afterDate,afterId,afterLine,limit));}
 public List<Map<String,String>> balances(UUID tenant){return tx(c->query(c,"SELECT a.id,a.currency,a.normal_side,coalesce(b.debits,0)::text AS debits,coalesce(b.credits,0)::text AS credits FROM ledger.account a LEFT JOIN ledger.account_balance b ON b.tenant_id=a.tenant_id AND b.account_id=a.id WHERE a.tenant_id=? ORDER BY a.id",tenant));}
}''')
java('ledger-persistence','Projector','''import java.util.*;import java.sql.*;
/** Per-event membership, never sequence MAX: an earlier allocated ID can commit later. */
public final class Projector {
 private final LedgerStore store;
 public Projector(LedgerStore s){store=s;}
 public UUID active(){return store.tx(c->UUID.fromString(LedgerStore.query(c,"SELECT generation FROM ledger.projection_head").getFirst().get("generation")));}
 public int drain(UUID generation){int n=0;while(true){int batch=store.tx(c->{var events=LedgerStore.query(c,"SELECT e.id,e.tenant_id,e.journal_id FROM ledger.outbox_event e WHERE NOT EXISTS(SELECT FROM ledger.projection_checkpoint p WHERE p.generation=? AND p.event_id=e.id) ORDER BY e.id LIMIT 100",generation);int count=0;for(var e:events){int inserted=LedgerStore.execute(c,"INSERT INTO ledger.projection_checkpoint(generation,event_id) VALUES(?,?) ON CONFLICT DO NOTHING",generation,Long.valueOf(e.get("id")));if(inserted==0)continue;LedgerStore.execute(c,"INSERT INTO ledger.reporting_balance SELECT ?,tenant_id,account_id,sum(CASE side WHEN 'DEBIT' THEN amount ELSE 0 END),sum(CASE side WHEN 'CREDIT' THEN amount ELSE 0 END) FROM ledger.posting WHERE tenant_id=? AND journal_id=? GROUP BY tenant_id,account_id ON CONFLICT(generation,tenant_id,account_id) DO UPDATE SET debits=ledger.reporting_balance.debits+excluded.debits,credits=ledger.reporting_balance.credits+excluded.credits",generation,UUID.fromString(e.get("tenant_id")),UUID.fromString(e.get("journal_id")));count++;}return count;});n+=batch;if(batch==0)return n;}}
 public long pending(){return store.tx(c->Long.valueOf(LedgerStore.query(c,"SELECT count(*) AS n FROM ledger.outbox_event e WHERE NOT EXISTS(SELECT FROM ledger.projection_checkpoint p JOIN ledger.projection_head h ON h.generation=p.generation WHERE p.event_id=e.id)").getFirst().get("n")));}
 public UUID replay(){var shadow=UUID.randomUUID();drain(shadow);store.tx(c->{// Fence posting/commit while verifying and promoting a complete source snapshot.
 LedgerStore.execute(c,"LOCK TABLE ledger.outbox_event IN SHARE MODE");var gaps=LedgerStore.query(c,"SELECT count(*) AS n FROM ((SELECT tenant_id,account_id,debits,credits FROM ledger.account_balance EXCEPT SELECT tenant_id,account_id,debits,credits FROM ledger.reporting_balance WHERE generation=?) UNION ALL (SELECT tenant_id,account_id,debits,credits FROM ledger.reporting_balance WHERE generation=? EXCEPT SELECT tenant_id,account_id,debits,credits FROM ledger.account_balance)) x",shadow,shadow);if(!gaps.getFirst().get("n").equals("0"))throw new IllegalStateException("SHADOW_MISMATCH_RETRY_WITH_NEW_GENERATION");LedgerStore.execute(c,"UPDATE ledger.projection_head SET generation=?",shadow);return null;});return shadow;}
 public static void main(String[] args)throws Exception{var s=new LedgerStore(System.getenv().getOrDefault("LEDGER_URL","jdbc:postgresql://localhost:18101/clearledger"),"clearledger_runtime",System.getenv().getOrDefault("LEDGER_PASSWORD","local-only-clearledger"));var p=new Projector(s);if(args.length>0&&args[0].equals("replay")){System.out.println(p.replay());return;}do{p.drain(p.active());Thread.sleep(500);}while(true);}
}''')
java('ledger-persistence','Reconciliation','''import java.util.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.math.*;import java.sql.*;
public final class Reconciliation {
 private final LedgerStore store;public Reconciliation(LedgerStore s){store=s;}
 public UUID ingest(UUID tenant,byte[] csv){if(csv.length>1048576)throw new IllegalArgumentException("IMPORT_BYTE_BOUND");var text=new String(csv,StandardCharsets.UTF_8);var lines=text.split("\\\\r?\\\\n",-1);if(lines.length>5002)throw new IllegalArgumentException("IMPORT_ROW_BOUND");if(!lines[0].equals("source_id,reference,currency,amount"))throw new IllegalArgumentException("CSV_HEADER");String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(csv));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}return store.tx(c->{var prior=LedgerStore.query(c,"SELECT id FROM ledger.statement_import WHERE tenant_id=? AND content_hash=?",tenant,hash);if(!prior.isEmpty())return UUID.fromString(prior.getFirst().get("id"));var id=UUID.randomUUID();LedgerStore.execute(c,"INSERT INTO ledger.statement_import(tenant_id,id,content_hash) VALUES(?,?,?)",tenant,id,hash);var sources=new HashSet<String>();for(int i=1;i<lines.length;i++){if(i==lines.length-1&&lines[i].isEmpty())continue;String source="",ref="",currency="";BigInteger amount=null;String status="UNMATCHED",reason="";try{var cols=parseLine(lines[i]);if(cols.size()!=4)throw new IllegalArgumentException("COLUMN_COUNT");source=cols.get(0);ref=cols.get(1);currency=cols.get(2);if(source.isBlank()||source.length()>120||ref.length()>120)throw new IllegalArgumentException("FIELD_BOUND");amount=Money.parse(currency,cols.get(3)).minor();if(amount.signum()==0)throw new IllegalArgumentException("ZERO_AMOUNT");if(!sources.add(source)){status="DUPLICATE";reason="DUPLICATE_SOURCE_ID";}}catch(IllegalArgumentException e){status="INVALID";reason=e.getMessage();}LedgerStore.execute(c,"INSERT INTO ledger.statement_row VALUES(?,?,?,?,?,?,?,?,?)",tenant,id,i,source,ref,currency,amount,status,reason);if(status.equals("UNMATCHED")){var candidates=LedgerStore.query(c,"SELECT p.journal_id,p.line_no FROM ledger.posting p JOIN ledger.journal j ON j.tenant_id=p.tenant_id AND j.id=p.journal_id WHERE p.tenant_id=? AND j.reference=? AND j.currency=? AND CASE p.side WHEN 'DEBIT' THEN p.amount ELSE -p.amount END=? AND NOT EXISTS(SELECT FROM ledger.reconciliation_match m WHERE m.tenant_id=p.tenant_id AND m.journal_id=p.journal_id AND m.line_no=p.line_no)",tenant,ref,currency,amount);if(candidates.size()==1){var v=candidates.getFirst();LedgerStore.execute(c,"INSERT INTO ledger.reconciliation_match VALUES(?,?,?,?,?)",tenant,id,i,UUID.fromString(v.get("journal_id")),Integer.valueOf(v.get("line_no")));LedgerStore.execute(c,"UPDATE ledger.statement_row SET status='MATCHED',reason='UNAMBIGUOUS_REFERENCE_CURRENCY_AMOUNT' WHERE tenant_id=? AND import_id=? AND row_no=?",tenant,id,i);}else if(candidates.size()>1)LedgerStore.execute(c,"UPDATE ledger.statement_row SET status='AMBIGUOUS',reason='MULTIPLE_CANDIDATES' WHERE tenant_id=? AND import_id=? AND row_no=?",tenant,id,i);}}return id;});}
 static List<String> parseLine(String line){var out=new ArrayList<String>();var b=new StringBuilder();boolean quoted=false,closed=false;for(int i=0;i<line.length();i++){char ch=line.charAt(i);if(ch=='"'){if(quoted&&i+1<line.length()&&line.charAt(i+1)=='"'){b.append('"');i++;}else if(quoted){quoted=false;closed=true;}else if(b.isEmpty()&&!closed)quoted=true;else throw new IllegalArgumentException("MALFORMED_QUOTE");}else if(ch==','&&!quoted){out.add(b.toString());b.setLength(0);closed=false;}else{if(closed)throw new IllegalArgumentException("TRAILING_QUOTE_TEXT");b.append(ch);}}if(quoted)throw new IllegalArgumentException("UNCLOSED_QUOTE");out.add(b.toString());return out;}
 public List<Map<String,String>> rows(UUID tenant,UUID id){return store.tx(c->LedgerStore.query(c,"SELECT row_no,source_id,reference,currency,amount::text,status,reason FROM ledger.statement_row WHERE tenant_id=? AND import_id=? ORDER BY row_no",tenant,id));}
 public void resolve(UUID tenant,UUID id,int row,UUID journal,int line,String actor,String reason,String evidence){if(actor==null||actor.isBlank()||reason==null||reason.isBlank()||evidence==null||evidence.isBlank()||reason.length()>1000||evidence.length()>4000)throw new IllegalArgumentException("DECISION_EVIDENCE");store.tx(c->{var valid=LedgerStore.query(c,"SELECT s.status FROM ledger.statement_row s JOIN ledger.posting p ON p.tenant_id=s.tenant_id JOIN ledger.journal j ON j.tenant_id=p.tenant_id AND j.id=p.journal_id WHERE s.tenant_id=? AND s.import_id=? AND s.row_no=? AND p.journal_id=? AND p.line_no=? AND j.currency=s.currency AND CASE p.side WHEN 'DEBIT' THEN p.amount ELSE -p.amount END=s.amount AND s.status IN('UNMATCHED','AMBIGUOUS') FOR UPDATE OF s",tenant,id,row,journal,line);if(valid.isEmpty())throw new IllegalArgumentException("INVALID_MANUAL_CANDIDATE");LedgerStore.execute(c,"INSERT INTO ledger.reconciliation_match VALUES(?,?,?,?,?)",tenant,id,row,journal,line);LedgerStore.execute(c,"INSERT INTO ledger.reconciliation_decision(tenant_id,import_id,row_no,actor,reason,evidence) VALUES(?,?,?,?,?,?)",tenant,id,row,actor,reason,evidence);LedgerStore.execute(c,"UPDATE ledger.statement_row SET status='MATCHED',reason='MANUAL_REVIEW' WHERE tenant_id=? AND import_id=? AND row_no=?",tenant,id,row);return null;});}
 public String export(UUID tenant,UUID id){var out=new StringBuilder("row_no,source_id,reference,currency,amount,status,reason\\n");for(var r:rows(tenant,id)){boolean first=true;for(var v:r.values()){if(!first)out.append(',');first=false;String value=v==null?"":v;if(!value.isEmpty()&&"=+-@\\t\\r".indexOf(value.charAt(0))>=0)value="'"+value;out.append('"').append(value.replace("\\\"","\\\"\\\"")).append('"');}out.append('\\n');}return out.toString();}
}''')
java('ledger-api','ClearLedgerApplication','''import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.core.*;import javax.crypto.spec.SecretKeySpec;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import java.util.*;
@SpringBootApplication
public class ClearLedgerApplication {
 public static void main(String[] args){SpringApplication.run(ClearLedgerApplication.class,args);}
 @Bean LedgerStore ledgerStore(){String url=System.getenv().getOrDefault("LEDGER_URL","jdbc:postgresql://127.0.0.1:18101/clearledger");if("true".equals(System.getenv("LEDGER_MIGRATE")))LedgerStore.migrate(url,"postgres",System.getenv().getOrDefault("LEDGER_ADMIN_PASSWORD","local-only-admin"));return new LedgerStore(url,"clearledger_runtime",System.getenv().getOrDefault("LEDGER_PASSWORD","local-only-clearledger"));}
 @Bean JwtDecoder decoder(org.springframework.core.env.Environment env){String issuer=env.getProperty("ledger.issuer","http://127.0.0.1:18109/dev-issuer");boolean dev=env.acceptsProfiles(org.springframework.core.env.Profiles.of("dev"));if(dev){String address=env.getProperty("server.address","127.0.0.1");if(!Set.of("127.0.0.1","::1","localhost").contains(address))throw new IllegalStateException("DEV_REQUIRES_LOOPBACK");var decoder=NimbusJwtDecoder.withSecretKey(new SecretKeySpec("clearledger-disposable-local-demo-key-32-bytes".getBytes(java.nio.charset.StandardCharsets.UTF_8),"HmacSHA256")).macAlgorithm(MacAlgorithm.HS256).build();decoder.setJwtValidator(validators(issuer));return decoder;}return protectedDecoder(issuer);}
 public static JwtDecoder protectedDecoder(String issuer){var d=(NimbusJwtDecoder)JwtDecoders.fromIssuerLocation(issuer);d.setJwtValidator(validators(issuer));return d;}
 static OAuth2TokenValidator<Jwt> validators(String issuer){return new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer(issuer),jwt->{try{UUID.fromString(jwt.getClaimAsString("tenant"));if(!jwt.getAudience().contains("clearledger")||jwt.getExpiresAt()==null||jwt.getSubject()==null)throw new IllegalArgumentException();return OAuth2TokenValidatorResult.success();}catch(RuntimeException e){return OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token"));}});}
 @Bean SecurityFilterChain security(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/health").permitAll().requestMatchers("/v1/reports/**").hasAuthority("SCOPE_ledger.admin").requestMatchers("/v1/reconciliation/**","/v1/statements/**").hasAuthority("SCOPE_ledger.reconcile").requestMatchers(org.springframework.http.HttpMethod.GET,"/v1/**").hasAuthority("SCOPE_ledger.read").requestMatchers("/v1/**").hasAuthority("SCOPE_ledger.write").anyRequest().denyAll()).oauth2ResourceServer(o->o.jwt(j->{})).build();}
}''')
java('ledger-api','LedgerController','''import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.http.*;import java.util.*;import java.time.*;
@RestController
public class LedgerController {
 private final LedgerStore store;private final Reconciliation reconciliation;private final Projector projector;
 public LedgerController(LedgerStore s){store=s;reconciliation=new Reconciliation(s);projector=new Projector(s);}
 UUID tenant(Jwt principal){return UUID.fromString(principal.getClaimAsString("tenant"));}
 public record AccountInput(String currency,Journal.Side normalSide,String name){}
 public record LineInput(UUID account,Journal.Side side,String amount){}
 public record JournalInput(UUID period,LocalDate date,String currency,String reference,List<LineInput> lines){Journal journal(){if(lines==null||lines.size()>100)throw new IllegalArgumentException("BATCH_BOUND");return new Journal(period,date,currency,reference,lines.stream().map(l->new Journal.Line(l.account(),l.side(),Money.parse(currency,l.amount()).minor())).toList());}}
 public record ReversalInput(LocalDate date){}
 public record Decision(UUID journal,int line,String reason,String evidence){}
 @GetMapping("/health") Map<String,String> health(){return Map.of("status","UP");}
 @PostMapping("/v1/accounts") Map<String,UUID> account(@AuthenticationPrincipal Jwt p,@RequestBody AccountInput in){return Map.of("id",store.account(tenant(p),in.currency(),in.normalSide(),in.name()));}
 @PostMapping("/v1/journals") Map<String,UUID> post(@AuthenticationPrincipal Jwt p,@RequestHeader("Idempotency-Key") String key,@RequestBody JournalInput in){return Map.of("journalId",store.post(tenant(p),key,in.journal()));}
 @PostMapping("/v1/journals/{id}/reversals") Map<String,UUID> reverse(@AuthenticationPrincipal Jwt p,@PathVariable UUID id,@RequestHeader("Idempotency-Key")String key,@RequestBody ReversalInput in){return Map.of("journalId",store.reverse(tenant(p),id,key,in.date()));}
 @GetMapping("/v1/requests/{key}") List<Map<String,String>> request(@AuthenticationPrincipal Jwt p,@PathVariable String key){return store.receipt(tenant(p),key);}
 @PostMapping("/v1/periods/{id}/close") Map<String,String> close(@AuthenticationPrincipal Jwt p,@PathVariable UUID id){store.close(tenant(p),id);return Map.of("status","CLOSED");}
 @GetMapping("/v1/accounts/{id}/statement") Map<String,Object> statement(@AuthenticationPrincipal Jwt p,@PathVariable UUID id,@RequestParam(defaultValue="1900-01-01")LocalDate afterDate,@RequestParam(defaultValue="00000000-0000-0000-0000-000000000000")UUID afterId,@RequestParam(defaultValue="0")int afterLine,@RequestParam(required=false)Instant boundary,@RequestParam(defaultValue="100")int limit){var cutoff=boundary==null?Instant.now():boundary;var rows=store.statement(tenant(p),id,afterDate,afterId,afterLine,cutoff,limit);return Map.of("consistency","serializable snapshot per page; recorded_at cutoff excludes newer recordings", "boundary",cutoff,"account",id,"rows",rows,"next",rows.isEmpty()?Map.of():Map.of("afterDate",rows.getLast().get("effective_date"),"afterId",rows.getLast().get("id"),"afterLine",rows.getLast().get("line_no")),"filters",Map.of("limit",limit));}
 @PostMapping(value="/v1/statements",consumes="text/csv") Map<String,UUID> ingest(@AuthenticationPrincipal Jwt p,@RequestBody byte[] csv){return Map.of("importId",reconciliation.ingest(tenant(p),csv));}
 @GetMapping("/v1/reconciliation/{id}") List<Map<String,String>> rows(@AuthenticationPrincipal Jwt p,@PathVariable UUID id){return reconciliation.rows(tenant(p),id);}
 @PostMapping("/v1/reconciliation/{id}/{row}/resolve") Map<String,String> resolve(@AuthenticationPrincipal Jwt p,@PathVariable UUID id,@PathVariable int row,@RequestBody Decision d){reconciliation.resolve(tenant(p),id,row,d.journal(),d.line(),p.getSubject(),d.reason(),d.evidence());return Map.of("status","MATCHED");}
 @GetMapping(value="/v1/reconciliation/{id}/export",produces="text/csv") String export(@AuthenticationPrincipal Jwt p,@PathVariable UUID id){return reconciliation.export(tenant(p),id);}
 @PostMapping("/v1/reports/replay") Map<String,UUID> replay(){return Map.of("generation",projector.replay());}
 @GetMapping("/v1/reports/freshness") Map<String,Object> freshness(){return Map.of("generation",projector.active(),"pendingEvents",projector.pending(),"authoritative",false);}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> invalid(IllegalArgumentException e){return ResponseEntity.unprocessableContent().body(Map.of("code",e.getMessage()==null?"INVALID_INPUT":e.getMessage()));}
 @ExceptionHandler(LedgerStore.LedgerException.class) ResponseEntity<Map<String,String>> db(LedgerStore.LedgerException e){return ResponseEntity.status(e.temporary?503:e.code.contains("CONFLICT")||e.code.contains("REVERSED")?409:422).body(Map.of("code",e.code,"retry",e.temporary?"same key after backoff":"correct input"));}
}''')
