(p/'ledger-domain/pom.xml').write_text((p/'ledger-domain/pom.xml').read_text().replace('</project>','<build><plugins><plugin><groupId>org.apache.maven.plugins</groupId><artifactId>maven-surefire-plugin</artifactId><configuration><includes><include>**/*Test.java</include><include>**/*Properties.java</include></includes></configuration></plugin></plugins></build></project>'))
java('ledger-persistence','ReconciliationTest','''import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import java.util.*;
class ReconciliationTest {@Test void csvIsBoundedAndQuoted(){assertEquals(List.of("a","b,c","JPY","2"),Reconciliation.parseLine("a,\\\"b,c\\\",JPY,2"));assertEquals(List.of("a\\\"b"),Reconciliation.parseLine("\\\"a\\\"\\\"b\\\""));for(String s:List.of("\\\"open","a\\\"bad","\\\"closed\\\"bad"))assertThrows(IllegalArgumentException.class,()->Reconciliation.parseLine(s));assertThrows(IllegalArgumentException.class,()->new Reconciliation(null).ingest(UUID.randomUUID(),new byte[1048577]));}}
''',True)
java('ledger-verification','CrashWriter','''import java.nio.file.*;import java.sql.*;import java.util.*;import java.time.*;import java.math.*;
/** A real subprocess intentionally killed by the integration suite at named transaction boundaries. */
public final class CrashWriter {public static void main(String[] a)throws Exception{var store=new LedgerStore(a[0],"clearledger_runtime","local-only-clearledger");var j=new Journal(UUID.fromString(a[2]),LocalDate.of(2026,1,2),"CAD","crash",List.of(new Journal.Line(UUID.fromString(a[3]),Journal.Side.DEBIT,BigInteger.TEN),new Journal.Line(UUID.fromString(a[4]),Journal.Side.CREDIT,BigInteger.TEN)));try(var c=DriverManager.getConnection(a[0],"clearledger_runtime","local-only-clearledger")){c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE);LedgerStore.postOn(c,UUID.fromString(a[1]),a[5],j,null,UUID.randomUUID());if(a[6].equals("after"))c.commit();Files.writeString(Path.of(a[7]),"READY");Thread.sleep(60000);}}}''')
java('ledger-verification','LedgerPostgresIT','''import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.testcontainers.postgresql.PostgreSQLContainer;import java.util.*;import java.math.*;import java.time.*;import java.sql.*;import java.util.concurrent.*;import java.nio.file.*;
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class LedgerPostgresIT {
 PostgreSQLContainer pg;LedgerStore store,admin;UUID tenant,other,period,a,b;
 @BeforeAll void boot(){pg=new PostgreSQLContainer("postgres:18.3-alpine").withDatabaseName("clearledger").withUsername("postgres").withPassword("local-only-admin");pg.start();LedgerStore.migrate(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());store=new LedgerStore(pg.getJdbcUrl(),"clearledger_runtime","local-only-clearledger");admin=new LedgerStore(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());}
 @AfterAll void stop(){if(pg!=null)pg.stop();}
 @BeforeEach void seed(){tenant=UUID.randomUUID();other=UUID.randomUUID();period=UUID.randomUUID();admin.tx(c->{LedgerStore.execute(c,"INSERT INTO ledger.tenant VALUES(?),(?)",tenant,other);LedgerStore.execute(c,"INSERT INTO ledger.accounting_period VALUES(?,?,DATE '2026-01-01',DATE '2026-12-31',false)",tenant,period);return null;});a=store.account(tenant,"CAD",Journal.Side.DEBIT,"cash");b=store.account(tenant,"CAD",Journal.Side.CREDIT,"sales");}
 Journal journal(int n,String ref){return new Journal(period,LocalDate.of(2026,1,2),"CAD",ref,List.of(new Journal.Line(a,Journal.Side.DEBIT,BigInteger.valueOf(n)),new Journal.Line(b,Journal.Side.CREDIT,BigInteger.valueOf(n))));}
 long count(String table){return admin.tx(c->Long.valueOf(LedgerStore.query(c,"SELECT count(*) n FROM ledger."+table+" WHERE tenant_id=?",tenant).getFirst().get("n")));}
 @Test void databaseMatchesIndependentGeneratedModelAndPrivileges(){var random=new Random(20261017);var ref=new ReferenceLedger();for(int i=0;i<80;i++){var j=journal(random.nextInt(100000)+1,"generated-"+i);store.post(tenant,"generated-"+i,j);ref.apply(j);}for(var row:store.balances(tenant)){var signed=new BigInteger(row.get("debits")).subtract(new BigInteger(row.get("credits")));assertEquals(ref.balances().get(UUID.fromString(row.get("id"))),signed);}assertThrows(LedgerStore.LedgerException.class,()->store.tx(c->LedgerStore.execute(c,"DELETE FROM ledger.posting WHERE tenant_id=?",tenant)));assertThrows(LedgerStore.LedgerException.class,()->store.tx(c->LedgerStore.execute(c,"UPDATE ledger.journal SET reference='tamper' WHERE tenant_id=?",tenant)));assertThrows(LedgerStore.LedgerException.class,()->store.tx(c->LedgerStore.execute(c,"UPDATE ledger.account SET currency='USD' WHERE tenant_id=?",tenant)));assertThrows(LedgerStore.LedgerException.class,()->store.post(other,"cross",journal(1,"cross")));var usd=store.account(tenant,"USD",Journal.Side.DEBIT,"usd");var invalid=new Journal(period,LocalDate.of(2026,1,2),"CAD","wrong",List.of(new Journal.Line(usd,Journal.Side.DEBIT,BigInteger.ONE),new Journal.Line(b,Journal.Side.CREDIT,BigInteger.ONE)));assertThrows(LedgerStore.LedgerException.class,()->store.post(tenant,"currency",invalid));assertEquals(80,count("journal"));}
 @Test void sixtyFourDuplicateRequestsAndRacingReversals()throws Exception{var pool=Executors.newFixedThreadPool(16);try{var start=new CountDownLatch(1);var futures=new ArrayList<Future<UUID>>();for(int i=0;i<64;i++)futures.add(pool.submit(()->{start.await();return store.post(tenant,"same",journal(100,"same"));}));start.countDown();var ids=new HashSet<UUID>();for(var f:futures)ids.add(f.get(60,TimeUnit.SECONDS));assertEquals(1,ids.size());assertEquals(1,count("journal"));assertThrows(LedgerStore.LedgerException.class,()->store.post(tenant,"same",journal(101,"same")));var original=ids.iterator().next();var reversed=new ArrayList<Future<Boolean>>();for(int i=0;i<8;i++){String key="rev-"+i;reversed.add(pool.submit(()->{try{store.reverse(tenant,original,key,LocalDate.of(2026,2,1));return true;}catch(LedgerStore.LedgerException e){return false;}}));}int ok=0;for(var f:reversed)if(f.get(60,TimeUnit.SECONDS))ok++;assertEquals(1,ok);assertEquals(2,count("journal"));for(var row:store.balances(tenant))assertEquals(row.get("debits"),row.get("credits"));}finally{pool.shutdownNow();}}
 @Test void closeRacesWritersWithoutPostingIntoClosedPeriod()throws Exception{var pool=Executors.newFixedThreadPool(8);try{var futures=new ArrayList<Future<?>>();for(int i=0;i<20;i++){String key="close-"+i;futures.add(pool.submit(()->{try{store.post(tenant,key,journal(1,key));}catch(LedgerStore.LedgerException expected){}}));}store.close(tenant,period);for(var f:futures)f.get(60,TimeUnit.SECONDS);assertThrows(LedgerStore.LedgerException.class,()->store.post(tenant,"late",journal(1,"late")));assertEquals("true",admin.tx(c->LedgerStore.query(c,"SELECT closed FROM ledger.accounting_period WHERE tenant_id=?",tenant).getFirst().get("closed")));}finally{pool.shutdownNow();}}
 @Test void actualProcessTerminationBeforeAndAfterCommit()throws Exception{for(String point:List.of("before","after")){var signal=Files.createTempFile("clearledger-crash-",".ready");Files.delete(signal);var command=List.of(System.getProperty("java.home")+"/bin/java","-Xmx96m","-cp",System.getProperty("java.class.path"),CrashWriter.class.getName(),pg.getJdbcUrl(),tenant.toString(),period.toString(),a.toString(),b.toString(),"crash-"+point,point,signal.toString());var process=new ProcessBuilder(command).redirectErrorStream(true).redirectOutput(ProcessBuilder.Redirect.INHERIT).start();try{long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(20);while(!Files.exists(signal)&&process.isAlive()&&System.nanoTime()<deadline)Thread.sleep(20);assertTrue(Files.exists(signal),"crash barrier must be reached");process.destroyForcibly().waitFor(10,TimeUnit.SECONDS);assertEquals(point.equals("after")?1:0,store.receipt(tenant,"crash-"+point).size());var replay=store.post(tenant,"crash-"+point,journal(10,"crash"));assertNotNull(replay);assertEquals(1,store.receipt(tenant,"crash-"+point).size());}finally{process.destroyForcibly();Files.deleteIfExists(signal);}}assertEquals(2,count("journal"));}
 @Test void projectionHandlesEarlierAllocatedEventCommittedLater()throws Exception{var projector=new Projector(store);try(var delayed=DriverManager.getConnection(pg.getJdbcUrl(),"clearledger_runtime","local-only-clearledger")){delayed.setAutoCommit(false);LedgerStore.postOn(delayed,tenant,"delayed",journal(10,"delayed"),null,UUID.randomUUID()); // later event uses independent tenant and period, avoiding deliberate period lock.
 var t2=UUID.randomUUID();var p2=UUID.randomUUID();admin.tx(c->{LedgerStore.execute(c,"INSERT INTO ledger.tenant VALUES(?)",t2);LedgerStore.execute(c,"INSERT INTO ledger.accounting_period VALUES(?,?,DATE '2026-01-01',DATE '2026-12-31',false)",t2,p2);return null;});var a2=store.account(t2,"CAD",Journal.Side.DEBIT,"a");var b2=store.account(t2,"CAD",Journal.Side.CREDIT,"b");store.post(t2,"later-id",new Journal(p2,LocalDate.of(2026,1,2),"CAD","later",List.of(new Journal.Line(a2,Journal.Side.DEBIT,BigInteger.ONE),new Journal.Line(b2,Journal.Side.CREDIT,BigInteger.ONE))));projector.drain(projector.active());delayed.commit();}assertTrue(projector.pending()>0);projector.drain(projector.active());assertEquals(0,projector.pending());assertEquals(0,projector.drain(projector.active()));var replay=projector.replay();assertEquals(replay,projector.active());assertEquals(0,projector.pending());}
 @Test void reconciliationDistinguishesRowsAndPreservesDuplicateImport(){store.post(tenant,"match",journal(100,"unique"));store.post(tenant,"amb1",journal(200,"ambiguous"));store.post(tenant,"amb2",journal(200,"ambiguous"));var csv=("source_id,reference,currency,amount\\n1,unique,CAD,1.00\\n2,ambiguous,CAD,2.00\\n3,missing,CAD,9.00\\n1,unique,CAD,1.00\\n4,bad,CAD,1.001\\n5,=SUM(A1),CAD,4.00\\n").getBytes(java.nio.charset.StandardCharsets.UTF_8);var r=new Reconciliation(store);var id=r.ingest(tenant,csv);assertEquals(id,r.ingest(tenant,csv));assertEquals(List.of("MATCHED","AMBIGUOUS","UNMATCHED","DUPLICATE","INVALID","UNMATCHED"),r.rows(tenant,id).stream().map(x->x.get("status")).toList());assertTrue(r.export(tenant,id).contains("'=SUM"));assertTrue(r.rows(other,id).isEmpty());var candidate=store.receipt(tenant,"amb1").getFirst().get("response");var jid=admin.tx(c->UUID.fromString(LedgerStore.query(c,"SELECT journal_id FROM ledger.idempotency_receipt WHERE tenant_id=? AND key='amb1'",tenant).getFirst().get("journal_id")));assertThrows(IllegalArgumentException.class,()->r.resolve(tenant,id,2,jid,1,"actor","","proof"));r.resolve(tenant,id,2,jid,1,"reviewer","bank evidence","statement row 2");assertEquals("MATCHED",r.rows(tenant,id).get(1).get("status"));assertEquals(1,count("reconciliation_decision"));}
 @Test void backupRestoreReauditsImmutableSource()throws Exception{store.post(tenant,"backup",journal(321,"backup"));var dump=pg.execInContainer("pg_dump","-U","postgres","-d","clearledger","--no-owner","--no-privileges");assertEquals(0,dump.getExitCode());try(var clean=new PostgreSQLContainer("postgres:18.3-alpine").withDatabaseName("restored").withUsername("postgres").withPassword("restore-only")){clean.start();clean.copyFileToContainer(org.testcontainers.utility.Transferable.of(dump.getStdout()),"/tmp/backup.sql");var restored=clean.execInContainer("psql","-v","ON_ERROR_STOP=1","-U","postgres","-d","restored","-f","/tmp/backup.sql");assertEquals(0,restored.getExitCode(),restored.getStderr());var restoredStore=new LedgerStore(clean.getJdbcUrl(),"postgres","restore-only");assertEquals(store.balances(tenant),restoredStore.balances(tenant));var violations=restoredStore.tx(c->LedgerStore.query(c,"SELECT journal_id FROM ledger.posting GROUP BY tenant_id,journal_id HAVING sum(CASE side WHEN 'DEBIT' THEN amount ELSE -amount END)<>0"));assertTrue(violations.isEmpty());new Projector(restoredStore).replay();}}
}''',True)
